import type { Metadata } from 'next';

/**
 * Tab icons (generated by packages/app-icons). Stage and production share one build, so the
 * environment is read at request time: QA and dev get a violet corner dot, stage a pink one.
 */
export function faviconSvgPath(env: string | undefined): string {
  switch ((env ?? '').toLowerCase()) {
    case 'qa':
    case 'development':
    case 'preview':
      return '/favicon-qa.svg';
    case 'stage':
    case 'staging':
      return '/favicon-stage.svg';
    default:
      return '/favicon.svg';
  }
}

/** ICO first for old browsers (sizes="32x32" so Chrome still prefers the SVG), then the SVG. */
export function appIcons(env: string | undefined): NonNullable<Metadata['icons']> {
  return {
    icon: [
      { url: '/favicon.ico', sizes: '32x32' },
      { url: faviconSvgPath(env), type: 'image/svg+xml' },
    ],
    apple: '/apple-touch-icon.png',
  };
}
